# Blog posts — insulins, other injectables and pipeline medicines. Insulin doses are never given as numbers.
from blog_glp1 import post

HYPO = ("<p><strong>Know your low-sugar plan.</strong> Signs include shaking, sweating, a fast heartbeat, hunger, confusion and irritability. "
        "A common approach is the rule of 15: take 15 g of fast-acting carbohydrate (glucose tablets, juice or regular soda), recheck after 15 minutes, and repeat if still low. "
        "Make sure someone close to you knows how to use rescue glucagon.</p>")
PEN = ("<ol><li>Check the label and the insulin's appearance before every dose.</li><li>Attach a new needle and do the safety (prime) shot the leaflet describes.</li>"
       "<li>Inject under the skin and hold the needle in for the time the leaflet says.</li><li>Rotate sites within an area to avoid lumpy skin (lipohypertrophy), which slows absorption.</li>"
       "<li>Never share pens, even with a new needle.</li></ol>")
COST35 = "<p>In the US, Medicare caps insulin out-of-pocket costs at $35 a month, and manufacturers run $35 programs for many people with commercial insurance or none. Check eligibility before paying list price.</p>"

POSTS_OTHER = [
post("mealtime-insulin-lispro-guide", "insulin-lispro", "Mealtime Insulin Lispro: Humalog, Admelog, Lyumjev",
     "How to time insulin lispro with meals — Humalog and Admelog vs faster Lyumjev — plus pen technique, pump use, low-sugar safety and $35 cost programs.",
     "Insulin lispro is a rapid-acting mealtime insulin. Humalog and Admelog are taken within 15 minutes before or right after a meal; Lyumjev, a faster formulation, at the start of a meal or within 20 minutes after starting. Your dose in units is always set individually.",
     [("Brands and why timing differs",
       "<p>Humalog (Lilly) and Admelog (Sanofi) are the same molecule at the same speed. Lyumjev contains added ingredients that speed absorption, so it is taken closer to eating. Lower-cost unbranded lispro is also available in the US.</p>"),
      ("Matching insulin to meals",
       "<p>Your care team may give you a fixed dose per meal or teach you to adjust by carbohydrate and current glucose. Write the plan down, including what to do when you skip a meal — usually, no meal means no mealtime insulin.</p>"),
      ("Pen technique", PEN),
      ("Pumps", "<p>Lispro is widely used in insulin pumps. If you use one, ask which formulation your pump is approved for and how often to change the reservoir.</p>"),
      ("Low blood sugar", HYPO),
      ("Storage and cost", "<p>Keep unopened insulin in the fridge; an in-use pen or vial lasts up to 28 days at room temperature.</p>" + COST35)],
     [("Can I inject lispro after eating?", "Humalog and Admelog can be taken right after a meal, and Lyumjev within 20 minutes after starting. Follow the plan your clinician gives you."),
      ("Is Humalog the same as Admelog?", "Both are insulin lispro with the same action profile, from different manufacturers."),
      ("Do I need lispro if I use basal insulin?", "It depends on your diabetes type and meals. Many people with type 1 need both; many with type 2 start with basal only.")],
     ["mealtime insulin", "insulin lispro"]),

post("novolog-vs-fiasp-timing", "insulin-aspart", "NovoLog vs Fiasp: Getting Mealtime Aspart Timing Right",
     "Insulin aspart comes as NovoLog (NovoRapid in Canada) and faster Fiasp. When to inject each, pen and pump tips, low-sugar safety and cost programs.",
     "NovoLog is injected 5–10 minutes before a meal; Fiasp, a faster version of insulin aspart, at the start of a meal or within 20 minutes after starting. Both are rapid-acting mealtime insulins dosed in units your clinician sets.",
     [("Same insulin, different speed",
       "<p>Fiasp adds ingredients that make aspart reach the blood faster. That makes it forgiving if you forget to dose before eating, but it also means less time between injection and the glucose drop. In Canada, NovoLog is sold as NovoRapid. Unbranded aspart is available in the US.</p>"),
      ("Pre-bolusing", "<p>With NovoLog, the 5–10 minute gap matters: injecting as you sit down can cause an early spike, while injecting much earlier can cause a low before the food arrives. Use your readings to discuss the right timing with your team.</p>"),
      ("Pen technique", PEN),
      ("Low blood sugar", HYPO),
      ("Storage and cost", "<p>Unopened: refrigerate. In use: up to 28 days at room temperature.</p>" + COST35)],
     [("Can I switch from NovoLog to Fiasp myself?", "No. Switching changes timing and sometimes dose; do it with your prescriber."),
      ("Is NovoRapid the same as NovoLog?", "Yes — NovoRapid is the Canadian brand name for insulin aspart."),
      ("Can aspart be used in a pump?", "Yes, both are used in pumps; check which your pump is approved for.")],
     ["mealtime insulin", "insulin aspart"]),

post("apidra-insulin-glulisine-guide", "insulin-glulisine", "Apidra (Insulin Glulisine): A Practical Mealtime Guide",
     "Using Apidra (insulin glulisine): timing with meals, pens and pumps, how it compares with lispro and aspart, low-sugar safety and storage.",
     "Apidra is a rapid-acting mealtime insulin taken within 15 minutes before or within 20 minutes after starting a meal. It works like lispro and aspart; the choice often comes down to coverage, pen preference and how your body responds.",
     [("How it compares", "<p>All three rapid-acting insulins — lispro, aspart and glulisine — start working within about 15 minutes and last a few hours. Apidra is made by Sanofi and comes in vials and SoloStar pens.</p>"),
      ("Using it day to day", "<p>Agree a clear plan with your team: a set dose per meal or a carbohydrate ratio, plus a correction rule for high readings. Skipped meal usually means skipped dose.</p>" + PEN),
      ("Pumps", "<p>Apidra can be used in pumps. Ask how often to change the infusion set and what to do if readings rise unexpectedly — a blocked set is a common cause.</p>"),
      ("Low blood sugar", HYPO),
      ("Storage", "<p>Unopened: refrigerate. In use: up to 28 days at room temperature.</p>")],
     [("Is Apidra interchangeable with Humalog?", "They are different insulins with similar action. Switching should be planned with your prescriber."),
      ("Can Apidra be mixed with other insulin?", "Only as the product labeling allows; ask your pharmacist before mixing any insulins."),
      ("What if my pharmacy doesn't stock it?", "Ask your prescriber whether lispro or aspart is a suitable alternative under your plan.")],
     ["mealtime insulin", "insulin glulisine"]),

post("regular-insulin-humulin-r-novolin-r", "regular-insulin", "Regular Insulin (Humulin R, Novolin R): Timing & Cost",
     "Regular human insulin explained: why it is taken 30 minutes before meals, over-the-counter U-100 vs prescription U-500, safety and low-cost options.",
     "Regular insulin is short-acting human insulin taken about 30 minutes before a meal. U-100 Humulin R and Novolin R are sold over the counter at many US pharmacies and are among the cheapest insulins; concentrated Humulin R U-500 needs a prescription.",
     [("How it differs from rapid-acting insulin", "<p>Regular insulin starts more slowly and lasts longer than lispro or aspart. That is why it is injected about half an hour before eating, and why lows can happen several hours after a meal.</p>"),
      ("Over the counter — but not without guidance", "<p>Being able to buy U-100 regular insulin without a prescription helps in a pinch, but switching from a modern insulin is not unit-for-unit simple. Talk to a clinician or pharmacist before you change, even for a short time.</p>"),
      ("U-500: a different product", "<p>Humulin R U-500 is five times more concentrated. It is prescribed for people who need very large doses and uses its own dedicated pen or syringe. Mix-ups between U-100 and U-500 can cause dangerous lows.</p>"),
      ("Low blood sugar", HYPO),
      ("Storage", "<p>Unopened: refrigerate. In use: follow the product labeling, often 31–42 days.</p>")],
     [("Can I inject regular insulin right before eating?", "It works best about 30 minutes before a meal. Ask your clinician how to adjust if that is hard to fit into your routine."),
      ("Is store-brand insulin the same?", "Store-brand human insulins are the same regular or NPH insulin sold under a pharmacy brand."),
      ("Is regular insulin used in emergencies?", "Hospitals use it intravenously; at home it is a mealtime insulin.")],
     ["human insulin", "short-acting insulin", "low cost"]),

post("nph-insulin-cloudy-insulin-guide", "nph-insulin", "NPH Insulin: How to Use Cloudy Insulin Safely",
     "NPH insulin (Humulin N, Novolin N) is cloudy and must be mixed before every dose. How to resuspend it, when it peaks, night-time lows and cost.",
     "NPH is an intermediate-acting human insulin, used once or twice daily for background control. It is cloudy and must be gently mixed before every dose. Because it peaks several hours after injection, meal and snack timing matter more than with modern basal insulins.",
     [("Mix it every time", "<p>NPH crystals settle. Roll the vial or pen between your hands and tip it gently, as the instructions describe, until it is evenly cloudy — do not shake hard. An unmixed dose can be too weak or too strong.</p>"),
      ("Understanding the peak", "<p>NPH has a peak a few hours after injection. If you take it at night, that peak can fall in the early morning hours. Ask your clinician whether you need a bedtime snack or a different timing, and check your sugar overnight if you feel unwell on waking.</p>"),
      ("Using it with other insulin", "<p>NPH is sometimes mixed with regular insulin in the same syringe, drawing clear before cloudy. Only do this if your team has taught you; premixed 70/30 insulins do it for you.</p>"),
      ("Low blood sugar", HYPO),
      ("Cost", "<p>NPH is available over the counter at many US pharmacies and is one of the lowest-cost insulins.</p>")],
     [("Why is my NPH cloudy but my other insulin clear?", "NPH is a suspension; cloudiness is normal. Clear insulins should never look cloudy."),
      ("Can NPH replace Lantus?", "Sometimes, for cost reasons, but the doses and timing differ. Switch only with your clinician's plan."),
      ("How many times should I roll the pen?", "Follow your product's leaflet; most say to roll and tip it until it looks uniformly white and cloudy.")],
     ["NPH", "basal insulin", "low cost"]),

post("insulin-glargine-lantus-basaglar-semglee-toujeo", "insulin-glargine", "Lantus, Basaglar, Semglee, Toujeo: Glargine Explained",
     "All the insulin glargine brands compared: Lantus, Basaglar, Semglee, Rezvoglar and concentrated Toujeo U-300 — switching rules, storage and savings.",
     "Insulin glargine is a once-daily basal insulin. Lantus, Basaglar, Semglee and Rezvoglar are U-100; Semglee and Rezvoglar are interchangeable biosimilars to Lantus. Toujeo is a concentrated U-300 form that is not unit-for-unit identical when switching.",
     [("Biosimilars, simply", "<p>An interchangeable biosimilar can be swapped for the original at the pharmacy, where state law allows, just like a generic. Semglee and Rezvoglar have that status for Lantus, which often lowers the price.</p>"),
      ("Toujeo is different", "<p>Toujeo holds three times as much insulin per mL. People switching from U-100 glargine often need a somewhat different dose. Do not convert doses yourself and never draw Toujeo into a regular syringe.</p>"),
      ("Daily routine", "<p>Inject once a day at the same time. Do not dilute glargine or mix it with other insulins.</p>" + PEN),
      ("Low blood sugar", HYPO),
      ("Storage", "<p>Unopened: refrigerate. In use: Lantus up to 28 days, Toujeo up to 56 days at room temperature.</p>" + COST35),
      ("What happened to Levemir?", "<p>Insulin detemir (Levemir) has been discontinued in the US. If you used it, your prescriber will have moved you to another basal insulin such as glargine or degludec.</p>")],
     [("Can I switch from Lantus to Semglee?", "Yes, they are interchangeable, and your pharmacist may substitute one for the other where permitted."),
      ("Morning or night?", "Either, as long as it is the same time each day. Your clinician may suggest a time based on your readings."),
      ("Is glargine safe in type 1 diabetes?", "Yes, it is approved for basal control in type 1 and type 2 diabetes.")],
     ["basal insulin", "insulin glargine", "biosimilar"]),

post("tresiba-degludec-flexible-timing", "insulin-degludec", "Tresiba (Degludec): Why Flexible Timing Matters",
     "Tresiba (insulin degludec) is an ultra-long basal insulin with flexible dose timing. How the 8-hour rule works, U-100 vs U-200 pens, storage and cost.",
     "Tresiba is an ultra-long-acting basal insulin taken once a day. Its long action allows flexible timing — the label only requires at least 8 hours between doses. It comes in U-100 and U-200 pens, and unbranded insulin degludec is available in the US.",
     [("The flexibility, in practice", "<p>If you normally inject at 8 a.m. but forget until lunchtime, you can still take that day's dose, as long as at least 8 hours separate it from the next one. That makes degludec useful for shift workers and travelers.</p>"),
      ("U-100 or U-200", "<p>U-200 pens hold twice the insulin per mL, so they suit people who need larger doses. The pen counter shows the units you get, so you do not need to convert — but never draw U-200 out of a pen with a syringe.</p>"),
      ("Who can use it", "<p>Tresiba is approved for basal control in diabetes in adults and children aged 1 and older.</p>"),
      ("Low blood sugar", HYPO),
      ("Storage", "<p>Unopened: refrigerate. In use: up to 56 days at room temperature or in the fridge.</p>" + COST35)],
     [("Can I take Tresiba at a different time every day?", "Yes, within the label's rule of at least 8 hours between doses. A regular time still helps you remember."),
      ("Tresiba or glargine?", "Both are basal insulins; degludec lasts longer and allows more flexible timing. Coverage often decides."),
      ("Why does it take days for dose changes to show?", "Because it is so long-acting, it takes a few days to reach a steady level after each change.")],
     ["basal insulin", "insulin degludec"]),

post("awiqli-once-weekly-insulin", "insulin-icodec", "Awiqli: What Once-Weekly Insulin Changes for You",
     "Awiqli (insulin icodec) is the first once-weekly basal insulin in the US. Who it is for, how switching from daily insulin works, and what to watch for.",
     "Awiqli replaces seven daily basal injections with one weekly shot. The FDA approved it on March 26, 2026 for adults with type 2 diabetes — not for type 1. Switching from daily insulin follows specific label instructions, so let your prescriber set the first doses.",
     [("Who it is for", "<p>Adults with type 2 diabetes who need basal insulin. For people who dislike daily injections or forget them, a weekly dose can make treatment easier to stick with.</p>"),
      ("How it is different", "<p>Icodec is highly concentrated (700 units/mL) and binds in the blood, releasing slowly over the week. Dose changes take time to show, so adjustments are usually made weekly rather than daily.</p>"),
      ("Switching from daily insulin", "<p>The label has a specific method for the first injection after daily basal insulin. Do not convert doses yourself. Plan more glucose checks in the first weeks.</p>"),
      ("Low blood sugar", HYPO),
      ("Cost and coverage", "<p>Pricing and insurance coverage were still settling after launch. Check your plan and the manufacturer's programs before you fill.</p>")],
     [("Can I use Awiqli for type 1 diabetes?", "No — in the US it is approved only for adults with type 2 diabetes."),
      ("Which day should I inject?", "Pick one day and keep it every week, as your prescriber advises."),
      ("Is it available in Canada?", "Yes — insulin icodec was approved in Canada and the EU before the US.")],
     ["weekly insulin", "insulin icodec", "type 2 diabetes"]),

post("premixed-insulin-70-30-guide", "premixed-insulin", "Premixed Insulin 70/30 and Mixes: Who They Suit",
     "Premixed insulins (Humulin and Novolin 70/30, Humalog Mix, NovoLog Mix) explained: what the numbers mean, meal timing, mixing technique and cost.",
     "Premixed insulins combine an intermediate-acting insulin with a rapid- or short-acting one in a fixed ratio, usually injected twice a day with meals. They suit people with regular meal times who want fewer injections. 70/30 human insulin is among the cheapest options.",
     [("What the numbers mean", "<p>In 70/30, 70% of the insulin is intermediate-acting and 30% short- or rapid-acting. Humalog Mix 75/25 and NovoLog Mix 70/30 use modern rapid-acting insulins; Humulin and Novolin 70/30 use human insulin.</p>"),
      ("Routine matters", "<p>Because each dose covers a meal and the hours after it, regular meals are important. Skipping a meal after a premixed dose can cause a low. Ask how to handle late or small meals.</p>"),
      ("Mixing technique", "<p>Premixed insulins are cloudy suspensions. Roll and tip the pen or vial gently until evenly cloudy before every dose.</p>" + PEN),
      ("Low blood sugar", HYPO),
      ("Storage and cost", "<p>Unopened: refrigerate. In use: follow the product labeling. Human-insulin 70/30 is available over the counter at many US pharmacies at low cost.</p>")],
     [("Is Humalog Mix the same as Humulin 70/30?", "No. They contain different insulins with different timing; do not swap them without your prescriber."),
      ("When do I inject?", "Timing depends on the product — modern mixes close to the meal, human 70/30 about 30 minutes before. Follow your label and plan."),
      ("Can I adjust the ratio?", "No. The ratio is fixed; if you need more flexibility, separate basal and mealtime insulins may suit you better.")],
     ["premixed insulin", "70/30", "low cost"]),

post("symlin-pramlintide-safety-guide", "symlin", "Symlin (Pramlintide): Using It Safely With Insulin",
     "Symlin (pramlintide) is an amylin analog added to mealtime insulin. Why insulin doses are cut at the start, how to avoid severe lows, and injection rules.",
     "Symlin is injected before major meals alongside mealtime insulin in type 1 or type 2 diabetes. It carries a boxed warning for severe low blood sugar, so mealtime insulin is usually reduced at the start and glucose is checked often.",
     [("What amylin does", "<p>Amylin is released with insulin after meals. Pramlintide mimics it: it slows stomach emptying, lowers glucagon after meals and increases fullness. The result is a smaller glucose rise after eating.</p>"),
      ("The boxed warning", "<p>Severe hypoglycemia can happen, especially in type 1 diabetes, usually within a few hours of the injection. Starting low, reducing mealtime insulin and checking glucose before and after meals are the safeguards. Do not drive or operate machinery until you know how it affects you.</p>"),
      ("Injection rules", "<ul><li>Inject before major meals only — skip it if you skip the meal.</li><li>Never mix Symlin with insulin in the same syringe; use separate sites.</li><li>Your dose in micrograms is set and increased by your prescriber.</li></ul>"),
      ("Low blood sugar", HYPO),
      ("Availability", "<p>Symlin is brand-only in the US and does not appear to be marketed in Canada; check the Drug Product Database.</p>")],
     [("Can I use Symlin without insulin?", "No. It is approved only as an add-on to mealtime insulin."),
      ("Does Symlin cause weight loss?", "It can reduce appetite, but it is approved for blood sugar control, not weight management."),
      ("What if I feel sick after starting?", "Nausea is common at first. Tell your prescriber — the dose may be kept lower for longer.")],
     ["pramlintide", "amylin", "insulin add-on"]),

post("glucagon-rescue-be-ready", "glucagon", "Glucagon Rescue: Gvoke, Baqsimi, GlucaGen — Be Ready",
     "Rescue glucagon for severe low blood sugar: nasal Baqsimi, Gvoke and Zegalogue pens, GlucaGen kits — how each works, who should carry one, and what to do after.",
     "Rescue glucagon treats severe low blood sugar when someone cannot safely eat or drink. Modern options — a nasal powder (Baqsimi) and ready-to-use pens or syringes (Gvoke, Zegalogue) — are much simpler than the old mixing kits. After giving it, call emergency services.",
     [("Who should have one", "<p>Anyone using insulin — and many people taking sulfonylureas — should ask about a rescue glucagon prescription. It is used by a family member, friend, coworker or teacher, so they need to know where it is and how it works.</p>"),
      ("The options", "<ul><li><strong>Baqsimi:</strong> a nasal powder sprayed into one nostril; no needle and no inhaling needed.</li><li><strong>Gvoke:</strong> a prefilled pen or syringe, injected under the skin.</li><li><strong>Zegalogue (dasiglucagon):</strong> a ready-to-use autoinjector or syringe.</li><li><strong>GlucaGen and generic kits:</strong> powder that must be mixed before injecting.</li></ul>"),
      ("Step by step in an emergency", "<ol><li>Give the glucagon following the device's own instructions.</li><li>Call 911 (US/Canada).</li><li>Turn the person on their side — they may vomit as they recover.</li><li>Once awake and able to swallow, give fast sugar, then a snack.</li></ol>"),
      ("Keep it ready", "<p>Store at room temperature and check the expiry date every few months. Keep one at home and one in a bag or at school or work. Practice with a trainer device if one is available.</p>"),
      ("Cost", "<p>Generic and brand options exist, and insurance usually covers rescue glucagon. Ask about two-packs so you can keep one in each place.</p>")],
     [("Can glucagon be given if I'm not sure the sugar is low?", "If the person is unconscious or cannot swallow and has diabetes treated with insulin, giving glucagon and calling 911 is the standard advice."),
      ("Does nasal glucagon work if I have a cold?", "Studies supported its use during colds and congestion; follow the product label."),
      ("What happens after glucagon?", "The person usually wakes within about 15 minutes. They still need emergency care and food once they can swallow.")],
     ["glucagon", "hypoglycemia", "emergency"]),

post("cagrisema-fda-review-2026", "cagrisema", "CagriSema in 2026: FDA Review, Trials and Timing",
     "CagriSema (cagrilintide + semaglutide) in 2026: the December 2025 FDA filing, REDEFINE trial results, expected decision and why online versions are fake.",
     "CagriSema combines the amylin analog cagrilintide with semaglutide in one weekly injection. Novo Nordisk filed it with the FDA on December 18, 2025 and expects a decision in Q4 2026. Until approval, it cannot legally be bought — anything sold online is not the real product.",
     [("How it works", "<p>Semaglutide acts on GLP-1 receptors; cagrilintide mimics amylin, another fullness hormone. Acting on both pathways is designed to reduce appetite more than either alone.</p>"),
      ("What the trials showed", "<p>In the phase 3 REDEFINE 1 trial in adults with obesity, average weight loss was around 20–23% after 68 weeks, depending on the analysis. Gastrointestinal side effects were the most common, as with other incretin medicines.</p>"),
      ("Timeline", "<ul><li>December 18, 2025: submitted to the FDA for chronic weight management.</li><li>Q4 2026: decision expected, according to Novo Nordisk.</li><li>Canada: not approved.</li></ul>"),
      ("Avoid “research” CagriSema", "<p>Websites selling cagrilintide or CagriSema “for research” are not selling an approved medicine. The FDA has warned sellers of unapproved GLP-1 products. If you want access now, the only legal route is a registered clinical trial.</p>")],
     [("When will CagriSema be available?", "Only after FDA approval; Novo Nordisk expects a decision in Q4 2026, and launch would follow."),
      ("Will it be stronger than Wegovy?", "Trial results suggest more average weight loss than semaglutide alone, but direct comparisons and the final label will decide."),
      ("Can I join a trial?", "Search ClinicalTrials.gov for cagrilintide studies near you.")],
     ["pipeline", "cagrilintide", "weight loss"]),

post("retatrutide-2026-trial-results", "retatrutide", "Retatrutide in 2026: Trial Results and What's Next",
     "Retatrutide, Lilly's GIP/GLP-1/glucagon triple agonist: TRIUMPH phase 3 results from July 2026, the planned 2027 FDA filing, and why online 'reta' is unsafe.",
     "Retatrutide is an investigational weekly injection that acts on three hormone receptors: GIP, GLP-1 and glucagon. Lilly reported positive TRIUMPH-2 and TRIUMPH-3 phase 3 results in July 2026 and plans to submit to the FDA in Q1 2027. It is not approved anywhere.",
     [("Why a triple agonist", "<p>Adding glucagon-receptor activity to GIP and GLP-1 is designed to increase energy use as well as reduce appetite. In the phase 2 trial, the highest dose produced average weight loss of about 24% at 48 weeks.</p>"),
      ("What is being studied", "<p>The TRIUMPH phase 3 program covers obesity, knee osteoarthritis pain and obstructive sleep apnea, among other conditions.</p>"),
      ("Timeline", "<ul><li>July 2026: positive TRIUMPH-2 and TRIUMPH-3 results announced.</li><li>Q1 2027: planned FDA submission.</li><li>Approval would follow review — typically months later.</li></ul>"),
      ("Why online “reta” is dangerous", "<p>Products sold as retatrutide online are unapproved, untested and of unknown content and dose. In August 2026 the FDA issued warning letters to online sellers of products marketed as retatrutide. Do not inject anything bought this way.</p>")],
     [("Is retatrutide approved?", "No. It is investigational, with an FDA submission planned for Q1 2027."),
      ("How is it different from tirzepatide?", "Tirzepatide acts on GIP and GLP-1; retatrutide adds glucagon receptors."),
      ("How can I get it legally?", "Only through a registered clinical trial — search ClinicalTrials.gov.")],
     ["pipeline", "retatrutide", "weight loss"]),
]
